select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Mistral Vibe (formerly Le Chat)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'L''assistant de Mistral AI, anciennement Le Chat : un agent IA personnel pour les tâches quotidiennes avec recherche web, documents et connecteurs, et Vibe CLI, un agent de code dans le terminal.',
  'Mistral AI''s assistant, renamed from Le Chat: a personal AI agent for everyday tasks with web search, documents and connectors, plus Vibe CLI, a terminal coding agent.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Allo' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Téléphonie d''entreprise française dopée à l''IA : des agents IA répondent aux appels, qualifient les contacts et prennent les rendez-vous, et chaque appel est transcrit et résumé.',
  'French AI business phone system: AI agents answer calls, qualify leads and book appointments, and every call is transcribed and summarized.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'fonio.ai' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Assistant téléphonique IA autrichien pour les entreprises germanophones : il répond aux appels jour et nuit, prend les rendez-vous et transmet les demandes.',
  'Austrian AI phone assistant for German-speaking businesses: answers calls around the clock, books appointments and passes on requests.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Tana' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Espace de travail pensé pour l''IA, pour les notes et les réunions : il rejoint et transcrit les réunions, extrait les tâches de vos notes et répond aux questions sur l''ensemble de vos connaissances.',
  'AI-native workspace for notes and meetings: it joins and transcribes meetings, pulls tasks from your notes and answers questions across your knowledge graph.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Raycast AI' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Lanceur pour Mac et Windows avec l''IA intégrée : réponses rapides, chat IA avec de nombreux modèles et agents qui agissent dans vos applications et extensions.',
  'Launcher for Mac and Windows with AI built in: Quick AI, AI chat with many models and agents that act through your apps and extensions.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Lumo' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'L''assistant IA de Proton, conçu en Suisse pour la confidentialité : les conversations sont chiffrées, vous seul pouvez les lire, et elles ne servent jamais à entraîner l''IA.',
  'Proton''s privacy-first AI assistant from Switzerland: chats are encrypted so only you can read them, and they are never used to train AI.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Text AI Agent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agent autonome de service client de Text (l''éditeur de LiveChat) qui répond aux chats, e-mails et messages sociaux à partir de vos sources et passe la main selon vos règles.',
  'Autonomous customer service agent from Text (the LiveChat company) that answers chat, email and social messages from your knowledge sources and hands off by your rules.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Cognigy' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme allemande d''agents IA de service client pour les grandes entreprises, au téléphone et par chat, avec base de connaissances IA, assistants pour conseillers et intégrations aux centres de contact.',
  'German enterprise platform for customer service AI agents across voice and chat, with knowledge AI, agent copilots and contact-center integrations.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'folk' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'CRM IA français pour les équipes qui vivent de leurs relations : enrichissement IA, résumés de réunion, prochaines étapes suggérées, e-mails personnalisés et serveur MCP pour les assistants.',
  'French AI CRM for relationship-driven teams: AI enrichment, meeting summaries, next-step suggestions, personalized emails and an MCP server for assistants.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Pigment AI Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme de planification financière avec des agents IA spécialisés : l''Analyste explique vos chiffres et le Modeler construit des modèles de planification à partir d''une description.',
  'Business planning platform with specialist AI agents: the Analyst explains your numbers and the Modeler builds planning models from a description.');

select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Mistral Vibe (formerly Le Chat)', 'Allo', 'fonio.ai', 'Tana', 'Raycast AI', 'Lumo', 'Text AI Agent', 'Cognigy', 'folk', 'Pigment AI Agents') order by e.name;
